#!/bin/sh
# Installs the Glove Plymouth theme (system boot and shutdown).
# The artwork is generated by code: ./target/release/glove-arte plymouth data/plymouth/glove
#   sudo ./data/install-plymouth.sh           installs and activates
#   sudo ./data/install-plymouth.sh --remove  goes back to the previous theme
set -e
dir="$(cd "$(dirname "$0")" && pwd)"
# Message language: Portuguese if the system locale is Portuguese, English otherwise.
case "${LC_ALL:-${LC_MESSAGES:-${LANG:-}}}" in pt*) lang=pt ;; *) lang=en ;; esac
t() { if [ "$lang" = pt ]; then printf '%s' "$1"; else printf '%s' "$2"; fi; }
say() { printf '%s\n' "$(t "$1" "$2")"; }

dest=/usr/share/plymouth/themes/glove
# The file name stays in Portuguese: existing installations already have it.
previous=/var/lib/glove-plymouth-anterior

if [ "$(id -u)" != 0 ]; then
    say "Rode com sudo." "Run with sudo." >&2
    exit 1
fi
if ! command -v plymouth >/dev/null 2>&1; then
    say "O Plymouth não está instalado." "Plymouth is not installed." >&2
    exit 1
fi

# Debian/Ubuntu pick the theme with update-alternatives; the others, with plymouth-set-default-theme.
current_theme() {
    if command -v plymouth-set-default-theme >/dev/null 2>&1; then
        plymouth-set-default-theme
    else
        readlink -f /usr/share/plymouth/themes/default.plymouth
    fi
}
rebuild_initramfs() {
    if command -v update-initramfs >/dev/null 2>&1; then update-initramfs -u
    elif command -v dracut >/dev/null 2>&1; then dracut -f
    elif command -v mkinitcpio >/dev/null 2>&1; then mkinitcpio -P
    fi
}

case "${1:-}" in
    --remove|--remover)
        if command -v plymouth-set-default-theme >/dev/null 2>&1; then
            plymouth-set-default-theme "$(cat "$previous" 2>/dev/null || echo spinner)"
        else
            update-alternatives --remove default.plymouth "$dest/glove.plymouth" || true
        fi
        rm -rf "$dest" "$previous"
        rebuild_initramfs
        say "Tema do Glove removido; voltou o anterior." "Glove theme removed; the previous one is back."
        exit 0
        ;;
esac

[ -f "$dir/plymouth/glove/glove.script" ] || {
    say "Gere a arte antes: ./target/release/glove-arte plymouth data/plymouth/glove" \
        "Generate the artwork first: ./target/release/glove-arte plymouth data/plymouth/glove" >&2
    exit 1
}
[ -f "$previous" ] || current_theme > "$previous"
mkdir -p "$dest"
install -m 644 "$dir"/plymouth/glove/* "$dest/"
if command -v plymouth-set-default-theme >/dev/null 2>&1; then
    plymouth-set-default-theme glove
else
    update-alternatives --install /usr/share/plymouth/themes/default.plymouth default.plymouth "$dest/glove.plymouth" 100
    update-alternatives --set default.plymouth "$dest/glove.plymouth"
fi
rebuild_initramfs
say "Pronto: o tema do Glove aparece no próximo início (o anterior foi anotado em $previous)." \
    "Done: the Glove theme shows on the next boot (the previous one was noted in $previous)."
